import re

UNITS = {"h": 3600, "m": 60}


def parse_duration(text):
    """'1h30m' -> 5400 seconds."""
    if not re.fullmatch(r"(?:[0-9]+[hm])+", text):
        raise ValueError(f"not a duration: {text!r}")
    return sum(int(n) * UNITS[unit] for n, unit in re.findall(r"([0-9]+)([hm])", text))

